function sortByReference(items: number[], order: number[]): number[] {
  const rank = new Map<number, number>();
  order.forEach((v, i) => rank.set(v, i));
  const key = (v: number) => rank.get(v) ?? order.length + v;
  return [...items].sort((a, b) => key(a) - key(b));
}

